def limits():
    return {'version':'4.5.0','configuration':{'statuses':{'max_media_attachments':5},'media_attachments':{'supported_mime_types':['image/png','video/mp4'],'image_size_limit':100000,'image_matrix_limit':1000,'video_size_limit':1000000,'video_matrix_limit':1000000,'video_frame_rate_limit':30,'description_limit':1500}}}


@pytest.fixture
def wire(monkeypatch):
    state={'caps':limits(),'upload':[(200,{'id':'1','type':'image','url':'https://example.invalid/1'})], 'poll':[], 'status':(200,{'id':'100','url':'https://example.invalid/100'}),'calls':[],'on_poll':None,'redirect':{},'on_upload':None}
    class Handler(http.server.BaseHTTPRequestHandler):
        def log_message(self,*a):pass
        def reply(self,code,body):
            data=body if isinstance(body,bytes) else json.dumps(body).encode();self.send_response(code);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(data)));self.end_headers();
            try:self.wfile.write(data)
            except (BrokenPipeError,ConnectionResetError):pass
        def do_GET(self):
            state['calls'].append(('GET',self.path,None,dict(self.headers)))
            if self.path=='/api/v2/instance':return self.reply(200,state['caps'])
            if state['on_poll']:state['on_poll']()
            self.reply(*state['poll'].pop(0))
        def do_POST(self):
            raw=self.rfile.read(int(self.headers['Content-Length']));state['calls'].append(('POST',self.path,raw,dict(self.headers)))
            if self.path in state['redirect']:
                self.send_response(state['redirect'][self.path]);self.send_header('Location','/must-not-follow');self.end_headers();return
            if self.path=='/api/v2/media':
                if state['on_upload']:state['on_upload']()
                self.reply(*state['upload'].pop(0))
            else:self.reply(*(state['status'].pop(0) if isinstance(state['status'],list) else state['status']))
    server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
    state['url']='http://127.0.0.1:'+str(server.server_port);monkeypatch.setattr(mm,'POLL_INTERVAL',0)
    try:yield state
    finally:server.shutdown();server.server_close();thread.join(3)


