def invoke(env,fm=None,*,veto=None):
    cfg,adapter,repo=env;fm=fm or {'media':[{'file':'a.png','alt':'赤い点'}]}
    manifest=media.manifest_for(fm,cfg);state=accounts.state_dir_for('alpha')
    inflight.write(state,file='fixture',started='2030-01-01T00:00:00+09:00')
    result=media_delivery.publish(adapter,base.Post(text='body'),cfg=cfg,fm=fm,manifest=manifest,state_dir=state,before_publish=veto)
    return result,inflight.read(state),manifest


def posts(wire,path):return [x for x in wire['calls'] if x[:2]==('POST',path)]


def test_wire_same_public_bytes_alt_order_and_private_journal(env,wire):
    cfg,adapter,repo=env;(repo/'b.png').write_bytes(png())
    wire['upload']=[(200,{'id':str(i),'type':'image','url':'https://example.invalid/'+str(i)}) for i in (8,3)]
    fm={'media':[{'file':'a.png','alt':'一行・二行 🌿'},{'file':'b.png','alt':'別の説明'}],'post_options':{'sensitive':True,'spoiler_text':'予告','language':'ja','focus':[[0.2,-1],[1,0]]}}
    result,journal,manifest=invoke(env,fm);assert result.post_id=='100' and journal['media']['phase']=='published'
    assert stat_mode(accounts.state_dir_for('alpha')+'/inflight.json')==0o600
    for call,row in zip(posts(wire,'/api/v2/media'),manifest['files']):
        msg=email.parser.BytesParser(policy=email.policy.default).parsebytes(('Content-Type: '+call[3]['Content-Type']+'\r\n\r\n').encode()+call[2])
        fields={p.get_param('name',header='Content-Disposition'):p for p in msg.iter_parts()}
        assert fields['description'].get_payload(decode=True).decode()==row['alt']
        assert hashlib.sha256(fields['file'].get_payload(decode=True)).hexdigest()==row['public_sha256']
        assert fields['file'].get_content_type()=='image/png'
    form=urllib.parse.parse_qs(posts(wire,'/api/v1/statuses')[0][2].decode())
    assert form['media_ids[]']==['8','3'] and form['sensitive']==['true'] and form['spoiler_text']==['予告']
    cap=mm.cached(cfg);assert cap['instance']==wire['url'] and cap['observed_at'] and cap['version']=='4.5.0'


def stat_mode(path):return os.stat(path).st_mode&0o777


@pytest.mark.parametrize('poll',[(200,{'id':'1','type':'image','url':'https://example.invalid/1'}),(422,{'error':'processing failed'}),(404,{'error':'absent'}),(500,{'error':'bad'}),(200,{'id':'2','type':'image','url':'https://example.invalid/2'}),(200,{'id':'1','type':'image','url':None})])
def test_pending_206_then_terminal(env,wire,poll):
    wire['upload']=[(202,{'id':'1','type':'image','url':None})];wire['poll']=[(206,{}),poll]
    result,journal,_=invoke(env)
    expected=poll[0]==200 and poll[1].get('id')=='1' and poll[1].get('url')
    assert bool(result.post_id)==bool(expected) and len(posts(wire,'/api/v1/statuses'))==int(bool(expected))
    if not expected:assert result.error and journal['media']['phase']=='held'


