def video_timing(rows,*,scale=1000):
    ticks=sum(n*d for n,d in rows);count=sum(n for n,d in rows)
    timing=box(b'mdhd',b'\0'*12+struct.pack('>II',scale,ticks)+b'\0'*4)
    sample=b'\0'*24+struct.pack('>HH',640,480)+b'\0'*50
    table=box(b'stts',b'\0'*4+struct.pack('>I',len(rows))+b''.join(struct.pack('>II',n,d) for n,d in rows))+box(b'stsz',b'\0'*4+struct.pack('>II',1,count))+box(b'stsd',b'\0'*4+struct.pack('>I',1)+box(b'avc1',sample))
    raw=mp4();needle=box(b'mdia',box(b'hdlr',b'\0'*8+b'vide'+b'\0'*12));replacement=box(b'mdia',box(b'hdlr',b'\0'*8+b'vide'+b'\0'*12)+timing+box(b'minf',box(b'stbl',table)))
    # Rebuild known fixture ancestors, never transform production bytes.
    mvhd=b'\0'*12+struct.pack('>II',scale,ticks)+b'\0'*80;tkhd=b'\0'*76+struct.pack('>II',640<<16,480<<16)
    return box(b'ftyp',b'isom\0\0\0\0isom')+box(b'moov',box(b'mvhd',mvhd)+box(b'trak',box(b'tkhd',tkhd)+replacement))+box(b'mdat',b'synthetic')


@pytest.mark.parametrize('rows,rate',[([(30,1000)],Fraction(30,1)),([(10,500),(20,1250)],Fraction(30,1)),([(31,1000)],Fraction(30,1))])
def test_video_average_not_instantaneous_rate(env,rows,rate):
    # First/second 30fps, third uses a different total frame count, same fps.
    cfg,adapter,repo=env;p=repo/'v.mp4';p.write_bytes(video_timing(rows,scale=30000))
    fd=os.open(p,os.O_RDONLY)
    try:w,h,actual=mediaformats.video_metrics(fd,p.stat().st_size)
    finally:os.close(fd)
    assert (w,h)==(640,480) and actual==rate


