@pytest.mark.parametrize('phase', ['prepared','uploading','processing','ready','publishing','published'])
def test_journal_fault_no_next_side_effect_and_restart_block(env,wire,monkeypatch,phase):
    cfg,adapter,repo=env
    if phase=='processing':wire['upload']=[(202,{'id':'1','type':'image','url':None})]
    original=media_delivery._save;failed=[]
    def save(name,data):
        if data['media']['phase']==phase:
            failed.append(phase);raise OSError('synthetic persistence failure')
        return original(name,data)
    monkeypatch.setattr(media_delivery,'_save',save)
    result,journal,_=invoke(env)
    assert failed and result.error and not result.post_id
    assert len(posts(wire,'/api/v2/media'))==int(phase not in ('prepared','uploading'))
    assert len(posts(wire,'/api/v1/statuses'))==int(phase=='published')
    count=len(wire['calls'])
    again=core.send_once('alpha',text='body',production_flag=True,confirm='irrelevant',adapter_factory=lambda *a:adapter,log=lambda _:None,media_rows=[{'file':'a.png','alt':'赤い点'}])
    assert again.action=='inflight' and len(wire['calls'])==count


@pytest.mark.parametrize('link',['symlink','hardlink','fifo'])
def test_media_private_journal_rejects_special_leaf(env,wire,link):
    cfg,adapter,repo=env;directory=Path(accounts.state_dir_for('alpha'));directory.mkdir(parents=True,exist_ok=True)
    target=directory/'inflight.json';outside=repo/'foreign';outside.write_text('{}')
    if link=='symlink':target.symlink_to(outside)
    elif link=='hardlink':os.link(outside,target)
    else:os.mkfifo(target)
    before=outside.read_bytes()
    with pytest.raises((OSError,ValueError)):media_delivery._save('alpha',{'media':{}})
    assert outside.read_bytes()==before and not wire['calls']


@pytest.mark.parametrize('directory_failure',[False,True])
def test_actual_file_and_directory_fsync_failure_no_false_return(env,monkeypatch,directory_failure):
    import stat
    cfg,adapter,repo=env;directory=Path(accounts.state_dir_for('alpha'));directory.mkdir(parents=True,exist_ok=True)
    target=directory/'inflight.json';target.write_text('{"old":true}');before=target.read_bytes();real=os.fsync;calls=[]
    def fail(fd):
        isdir=stat.S_ISDIR(os.fstat(fd).st_mode)
        if isdir==directory_failure:calls.append(isdir);raise OSError('synthetic fsync EIO')
        real(fd)
    monkeypatch.setattr(media_delivery.os,'fsync',fail)
    with pytest.raises(OSError):media_delivery._save('alpha',{'new':True})
    assert calls and not list(directory.glob('.media-inflight-*'))
    assert (target.read_bytes()==before)==(not directory_failure)


