@pytest.mark.parametrize('drift',['none','alt','body','order','revoke'])
def test_v1_git_approve_publish_and_final_drift_veto(tmp_path,isolated_account_factory,wire,monkeypatch,drift):
    from tests.conftest import init_git_pair,make_queue_text,run_git,approve_via_cli
    from thth import queuefile
    name='alpha';raw=make_queue_text({'account':name,'status':'draft','approved_sha':'','topic':''},body='## mastodon\n\n本文。\n',media='mastodon')
    raw=raw.replace('\n---\n','\nmedia:\n  - file: a.png\n    alt: 点A\n  - file: b.png\n    alt: 点B\n---\n',1)
    pair=init_git_pair(tmp_path,seed_content=raw);repo=Path(pair['work']);path=Path(pair['queue_dir'])/'a.md'
    (repo/'a.png').write_bytes(png());(repo/'b.png').write_bytes(png())
    run_git(str(repo),['add','.']);run_git(str(repo),['commit','-m','synthetic media']);run_git(str(repo),['push'])
    account=isolated_account_factory(name=name,repo_dir=str(repo),media='mastodon',instance=wire['url'],production=True,hashtags=False,char_limit=500,quiet_hours=None,min_interval_hours=0)
    approved=approve_via_cli(path);assert approved.returncode==0,approved.stderr
    token=secrets.token_urlsafe(32);monkeypatch.setattr(accounts,'load_token',lambda _: {'access_token':token})
    adapter=mastodon.MastodonAdapter(instance=wire['url'],access_token=token)
    wire['upload']=[(202,{'id':'1','type':'image','url':None}),(200,{'id':'2','type':'image','url':'https://example.invalid/2'})]
    wire['poll']=[(200,{'id':'1','type':'image','url':'https://example.invalid/1'})]
    def mutate():
        if drift!='none':
            before=path.read_text();after=before.replace('status: approved','status: draft') if drift=='revoke' else before.replace('点A','別のalt') if drift=='alt' else before.replace('本文。','変更本文。') if drift=='body' else before.replace('file: a.png','file: temporary.png').replace('file: b.png','file: a.png').replace('file: temporary.png','file: b.png')
            path.write_text(after)
    wire['on_poll']=mutate
    result=core.throw_once(name,production_flag=True,adapter_factory=lambda *a:adapter,log=lambda _:None,bypass_pace=True)
    if drift=='none':
        assert result.action=='post',result
        assert queuefile.parse(str(path)).get('status')=='posted'
    else:
        assert result.action=='inflight' and not posts(wire,'/api/v1/statuses')
        assert queuefile.parse(str(path)).get('status')==('draft' if drift=='revoke' else 'approved')


