    run_git(str(repo),['add','.']);run_git(str(repo),['commit','-m','synthetic files']);run_git(str(repo),['push'])
    isolated_account_factory(name='alpha',repo_dir=str(repo),media='mastodon',instance=wire['url'],production=True,hashtags=False,char_limit=500,quiet_hours=None,min_interval_hours=0)
    approved=approve_via_cli(repo/REL);assert approved.returncode==0,approved.stderr
    token=secrets.token_urlsafe(32);monkeypatch.setattr(accounts,'load_token',lambda _: {'access_token':token})
    adapter=mastodon.MastodonAdapter(instance=wire['url'],access_token=token)
    wire['upload']=[(200,{'id':str(i),'type':'image','url':'https://example.invalid/'+str(i)}) for i in (1,2)]
    wire['status']=[(200,{'id':'100'}),(200,{'id':'101'})]
    if late=='second_upload_error':wire['upload'][1]=(500,{})
    if late in ('revoke','deadline'):
        wire['upload'][0]=(202,{'id':'1','type':'image','url':None})
        wire['poll']=[(200,{'id':'1','type':'image','url':'https://example.invalid/1'})]
        def stop():
            if late=='revoke':(repo/REL).write_text((repo/REL).read_text().replace('status: approved','status: draft'))
            else:monkeypatch.setattr(__import__('thth.jst',fromlist=['now_jst']),'now_jst',lambda:now+datetime.timedelta(hours=2))
        wire['on_poll']=stop
    results=threadthrow.publish_bundle('alpha',REL,adapter_factory=lambda *a:adapter,now=now,log=lambda _:None)
    if late!='none':
        assert not any(r.action=='published' for r in results[1:])
        assert len(posts(wire,'/api/v1/statuses'))==int(late=='second_upload_error')
        assert inflight.read(accounts.state_dir_for('alpha')) is not None
        previous=len(wire['calls']);again=threadthrow.publish_bundle('alpha',REL,adapter_factory=lambda *a:adapter,now=now,log=lambda _:None)
        assert len(wire['calls'])==previous and all(r.action!='published' for r in again)
        return
    assert [r.action for r in results]==['published','published'],results
    requests=posts(wire,'/api/v1/statuses');assert len(requests)==2
    assert urllib.parse.parse_qs(requests[1][2].decode())['in_reply_to_id']==['100']
    run=threadrun.load(results[0].run_id);assert [row['media'][0]['remote_id'] for row in run['posts']]==['1','2']


