def test_processing_deadline_preserves_known_id_and_does_not_post(env,wire,monkeypatch):
    wire['upload']=[(202,{'id':'1','type':'image','url':None})]
    original=mm.time.monotonic;counter=[0]
    def clock():counter[0]+=1;return 1000+counter[0]*200
    monkeypatch.setattr(mm.time,'monotonic',clock)
    result,journal,_=invoke(env)
    assert result.failure=='media_held' and result.error=='media_processing_timeout'
