def test_real_snapshot_bytes_not_changed_source_after_upload(env,wire):
    cfg,adapter,repo=env;original=(repo/'a.png').read_bytes()
    wire['on_upload']=lambda:(repo/'a.png').write_bytes(b'X'*len(original))
    result,journal,manifest=invoke(env)
    payload=posts(wire,'/api/v2/media')[0]
    msg=email.parser.BytesParser(policy=email.policy.default).parsebytes(('Content-Type: '+payload[3]['Content-Type']+'\r\n\r\n').encode()+payload[2])
    sent=next(p.get_payload(decode=True) for p in msg.iter_parts() if p.get_filename())
    assert sent==original and hashlib.sha256(sent).hexdigest()==manifest['files'][0]['public_sha256']
    assert 'source_changed' in result.error and not posts(wire,'/api/v1/statuses')


