def test_sent_record_failure_is_bounded_keeps_published_intent(env,wire,monkeypatch):
    from thth import sent
    cfg,adapter,repo=env;rows=[{'file':'a.png','alt':'点'}]
    first=core.send_once('alpha',text='',media_rows=rows,adapter_factory=lambda *a:adapter,log=lambda _:None)
    def fail(*a,**k):raise OSError('synthetic sent write failure')
    monkeypatch.setattr(sent,'write',fail)
    done=core.send_once('alpha',text='',media_rows=rows,production_flag=True,confirm=first.digest,adapter_factory=lambda *a:adapter,log=lambda _:None)
    assert done.action=='inflight' and done.post_id=='100' and done.error=='media_record_unconfirmed'
    journal=inflight.read(accounts.state_dir_for('alpha'));assert journal['media']['phase']=='published'
    before=len(wire['calls']);again=core.send_once('alpha',text='',media_rows=rows,production_flag=True,confirm=first.digest,adapter_factory=lambda *a:adapter,log=lambda _:None)
    assert again.action=='inflight' and len(wire['calls'])==before


def test_stop_during_processing_retains_intent_no_new_status_or_state(env,wire):
    from thth import leave_gate
    cfg,adapter,repo=env;leave_gate.bind(adapter,cfg)
    wire['upload']=[(202,{'id':'1','type':'image','url':None})];wire['poll']=[(200,{'id':'1','type':'image','url':'https://example.invalid/1'})]
    before=[]
    def stop():
        before.append(Path(accounts.state_dir_for('alpha'),'inflight.json').read_bytes())
        leaf=leave_gate.location()/'alpha.json';leaf.write_text('{}');leaf.chmod(0o600)
    wire['on_poll']=stop
    result,journal,_=invoke(env)
    assert result.error=='account_stopped' and result.failure=='media_held'
    assert not posts(wire,'/api/v1/statuses') and journal['media']['phase']=='processing'
    assert Path(accounts.state_dir_for('alpha'),'inflight.json').read_bytes()==before[0]


def test_public_lint_overlimit_and_missing_capabilities_are_errors(env,wire):
    from thth import lint
    cfg,adapter,repo=env;path=repo/'draft.md'
    path.write_text('---\nthth: 1\naccount: alpha\nstatus: draft\npublish_at: 2030-01-01T12:00:00+09:00\nmedia:\n  - file: a.png\n    alt: 点\n---\n## mastodon\n\n本文\n')
    wire['caps']['configuration']['media_attachments']['image_size_limit']=1
    errors=[e for e in lint.lint_file(str(path)) if not lint.is_warning(e)]
    assert 'media_limit_exceeded: bytes' in errors
    del wire['caps']['configuration']['media_attachments']['image_size_limit']
    errors=[e for e in lint.lint_file(str(path)) if not lint.is_warning(e)]
    assert any('media_capability_unavailable' in e for e in errors)
    assert not posts(wire,'/api/v2/media') and all('Authorization' not in call[3] for call in wire['calls'])


